properties.query:
// Detects the use of the lazagne attacker tool
let Parent_Process = dynamic(["cmd.exe","powershell.exe"]);
let cmd_all = dynamic(["all"]);
let cmd_any = dynamic(["-oN","-oJ","-oA","-quiet","-vv"]);
let query1 = 
_Im_ProcessCreate(parentprocess_has_any=Parent_Process,commandline_has_all=cmd_all,commandline_has_any=cmd_any);
let cmd_any2 = dynamic(["all","browsers","windows","sysadmin","memory","databases"]);
let query2 = 
_Im_ProcessCreate(parentprocess_has_any=Parent_Process,commandline_has_any=cmd_any2,targetprocess_has_any="lazagne.exe");
union isfuzzy=true
query1,query2
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
